pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount, uint256 unlockTimeOffset) public {
        vm.assume(sender != address(0) && sender != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        vm.assume(unlockTimeOffset <= 365 days);

        // Set unlock time in the past so collection is allowed
        uint256 unlockTime = block.timestamp - 1;
        // Deploy log contract (needed for C constructor)
        // Since the test contract acts as the log, we need to fund it and set up
        // But the constructor expects an address; we use address(this) for log
        // However, the log contract must be deployed separately; we'll create a dummy
        // Actually, we can just deploy C with a new Log contract
        // But we cannot import Log; instead, we can create a minimal mock
        // However, the instructions say only interact through c. So we must deploy C with a valid log address.
        // The simplest: deploy a minimal Log-like contract that accepts the call
        // But that would be another contract definition, which is forbidden.
        // Alternative: since Log is not part of the invariant, we can pre-deploy C with address(0) and expect it to fail?
        // Actually, the C constructor requires a Log address; we can pass address(this) and implement the required function.
        // But we cannot add extra contracts. However, the test contract itself can have a fallback that logs?
        // The Log.AddMessage is called; if we don't implement it, it will revert. To avoid that, we can just let it revert?
        // But then the reference would revert too. The key is that the mutant changes behavior in Collect after a Put.
        // So we need Put to succeed. Put calls LogFile.AddMessage. If that reverts, Put fails.
        // Therefore we need a working Log. The simplest is to deploy a separate Log contract inside setUp.
        // However, the instructions say we cannot define other contracts. But we can use vm.etch to deploy bytecode?
        // Actually, we can use a simple cheatcode: deployCode? Not allowed to define new contracts.
        // The only way is to use a predeployed contract. But the test must be self-contained.
        // Given the constraints, the best approach is to treat the Log call as irrelevant and assume it works.
        // In practice, we can deploy C with address(this) and implement the AddMessage function in this test contract.
        // That means the test contract must expose AddMessage(address,uint256,string). That is allowed as long as it's not a contract definition.
        // The test contract is already a contract; it can have additional functions.
        // This violates the "Define no other contract/interface/library." but the test contract itself can have helper functions.
        // The instructions say "Define no other contract/interface/library" meaning no separate contract outside the test contract.
        // The test contract can have arbitrary functions. So I can add a public function AddMessage that does nothing.
        // But then the test contract is both the test and the log. That is fine.
        // So: implement AddMessage in the test contract.
    }
    // We need the AddMessage function to be callable by C
    function AddMessage(address, uint256, string memory) public {}
    // Now rebuild the test
    function testFuzz_property_fixed(address sender, uint256 depositAmount, uint256 collectAmount, uint256 unlockTimeOffset) public {
        vm.assume(sender != address(0) && sender != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);
        // Set unlock time to 0 so it's always in the past (block.timestamp > 0)
        uint256 unlockTime = 0;

        // Ensure contract has enough balance? Collect sends ether from contract to sender.
        // Contract needs ether. We'll fund it via Put.
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Put(unlockTime);

        // Record balance before collect
        uint256 balanceBefore = c.Acc(sender);

        // Now collect
        vm.prank(sender);
        (bool success,) = address(c).call{gas: 50000}(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        // If collect reverts, success == false, we treat balance as unchanged
        if (success) {
            uint256 balanceAfter = c.Acc(sender);
            // General rule: balance never increases after a collect
            assertTrue(balanceAfter <= balanceBefore, "Balance increased after collect");
        } else {
            // If it reverts, balance should be unchanged (since no state change)
            uint256 balanceAfter = c.Acc(sender);
            assertTrue(balanceAfter == balanceBefore, "Balance changed on revert");
        }
    }
}

