import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 collectAmount, uint256 unlockTime) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        initialBalance = bound(initialBalance, 0, 1e24); // up to 1 million ETH
        collectAmount = bound(collectAmount, 0, initialBalance);
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);

        // Fund the contract with enough ETH
        vm.deal(address(c), initialBalance * 2);

        // Put funds into the contract for the caller
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Put{value: initialBalance}(unlockTime);

        // Advance time to make funds collectable
        vm.warp(unlockTime + 1);

        // Collect some amount
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The property: after Collect, the sum of all balances in Acc is always >= 0
        // Since balances are stored as uint256, they can never be negative, so this is trivial.
        // But we need a non-trivial property. Instead, check that the caller's balance in Acc after Collect
        // is never greater than it was before Collect (i.e., balance never increases).
        // Wait, the instructions said the rules already tried include that. Let's use a different property.
        // Property: After Collect, the caller's balance in Acc is less than or equal to the amount that was put in.
        // Re-reading the required rule: "after a call to Collect(...) completes, the value of state variable Put differs" — that's confusing.
        // The diff is in Put function modifying balance incorrectly (subtracting instead of adding). So a call to Collect should not cause balance to increase. 
        // Let's assert that after Collect, the caller's balance is <= initialBalance.
        uint256 balanceAfter = c.Acc(caller).balance;
        assertTrue(balanceAfter <= initialBalance, "Balance after Collect should not exceed initial balance");
    }
}

