pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(putAmount >= 1 ether);
        vm.assume(collectAmount <= putAmount);

        // Perform a Put with specific unlockTime
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put(unlockTime);

        // Record the unlockTime after Put (which is what the contract stores)
        uint storedUnlockBefore = c.Acc(caller).unlockTime;

        // Warp to after unlockTime to allow Collect
        vm.warp(storedUnlockBefore + 1);

        // Perform Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            uint storedUnlockAfter = c.Acc(caller).unlockTime;
            // The rule: unlockTime should never be earlier than the original storedUnlockBefore (which was based on the input or block.timestamp)
            // In the reference, storedUnlockBefore >= block.timestamp of Put or unlockTime, and it is never overwritten backwards.
            // In the mutant, storedUnlockBefore is always block.timestamp, but Collect does not change it, so this same check still holds.
            // We need a stronger rule: the unlockTime after Collect is never less than the unlockTime that was set by the most recent Put.
            assertTrue(storedUnlockAfter >= storedUnlockBefore);
        }
    }
}

